// Stroke icon on a 24x24 grid. Weight follows the --icon-stroke custom property (default 2).
export function icon(name, size = 20, className = '') {
  const wrap = document.createElement('span');
  wrap.className = 'icon ' + className;
  wrap.setAttribute('aria-hidden', 'true');
  wrap.style.setProperty('--s', size + 'px');
  wrap.innerHTML = `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="var(--icon-stroke, 2)" stroke-linecap="round" stroke-linejoin="round">${PATHS[name] || ''}</svg>`;
  return wrap;
}

